<template><main class="admin-content"><NuxtLink to="/admin/purchasing" class="text-sm font-bold text-blue-600">← Purchasing</NuxtLink><div class="mt-2 flex flex-wrap items-end justify-between gap-4"><div><h1 class="text-3xl font-black">Purchasing & Stock Intelligence</h1><p class="text-slate-500">Reorder recommendations, stock cover, slow stock and supplier purchasing suggestions.</p></div><button class="secondary" @click="load">Refresh</button></div>
<div class="mt-5 grid gap-3 md:grid-cols-3 xl:grid-cols-6"><div class="card"><small>Inventory Value</small><b>{{money(d.summary?.inventory_value)}}</b></div><div class="card"><small>Recommended Purchase</small><b>{{money(d.summary?.recommended_purchase_value)}}</b></div><div class="card"><small>Low / At Risk</small><b>{{d.summary?.low_stock||0}}</b></div><div class="card"><small>On Order Units</small><b>{{d.summary?.on_order_units||0}}</b></div><div class="card"><small>Slow / Excess</small><b>{{(d.summary?.slow_stock||0)+(d.summary?.excess_stock||0)}}</b></div><div class="card"><small>Dead Stock Value</small><b>{{money(d.summary?.dead_stock_value)}}</b></div></div>
<section class="panel mt-5 p-5"><div class="flex flex-wrap items-end gap-3"><label class="text-sm font-bold">Sales history<select v-model.number="days" class="input mt-1" @change="load"><option :value="30">30 days</option><option :value="60">60 days</option><option :value="90">90 days</option><option :value="180">180 days</option><option :value="365">365 days</option></select></label><label class="text-sm font-bold">Target stock cover<select v-model.number="target" class="input mt-1" @change="load"><option :value="30">30 days</option><option :value="60">60 days</option><option :value="90">90 days</option></select></label><input v-model="search" class="input max-w-xs" placeholder="Search product / SKU / supplier"><select v-model="health" class="input max-w-xs"><option value="">All stock health</option><option value="critical">Critical</option><option value="low">Low</option><option value="slow">Slow</option><option value="excess">Excess</option><option value="dead">Dead</option><option value="healthy">Healthy</option></select><button class="secondary" @click="csv">Export CSV</button></div></section>
<div v-if="err" class="mt-4 rounded-xl bg-red-50 p-4 text-red-700">{{err}}</div><section class="panel mt-5 p-5"><div class="flex items-center justify-between"><div><h2 class="text-xl font-black">Reorder & Stock Health</h2><p class="text-sm text-slate-500">Suggested order quantity accounts for current stock and open purchase orders.</p></div></div><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[1200px] text-sm"><thead><tr class="border-b text-left"><th class="p-2">Product</th><th>Supplier</th><th class="text-right">Stock</th><th class="text-right">Low / Reorder / Target</th><th class="text-right">On Order</th><th class="text-right">Sold</th><th class="text-right">Cover</th><th>Status</th><th class="text-right">Suggested</th><th class="text-right">Cost</th></tr></thead><tbody><tr v-for="x in filtered" :key="x.id" class="border-b"><td class="p-2"><b>{{x.name}}</b><div class="text-xs text-slate-500">{{x.sku||'No SKU'}}</div></td><td>{{x.supplier_name||'Unassigned'}}<div class="text-xs text-slate-500">{{x.supplier_sku||''}}</div></td><td class="text-right">{{x.stock}}</td><td class="text-right text-xs">{{x.low_stock_level}} / {{x.reorder_level}} / {{x.target_stock_level}}</td><td class="text-right">{{x.on_order}}</td><td class="text-right">{{x.sold_units}}</td><td class="text-right">{{x.stock_cover_days==null?'—':x.stock_cover_days+' days'}}</td><td><span :class="badge(x.health)">{{x.health}}</span></td><td class="text-right font-black">{{x.suggested_order}}</td><td class="text-right">{{money(x.suggested_cost)}}</td></tr></tbody></table></div></section>
<section class="panel mt-5 p-5"><h2 class="text-xl font-black">Supplier Purchase Suggestions</h2><p class="text-sm text-slate-500">Create a draft purchase order from the current recommendations. You can review and edit it in Suppliers & Purchases before sending.</p><div class="mt-4 grid gap-4 lg:grid-cols-2"><div v-for="g in supplierGroups" :key="g.id" class="rounded-xl border p-4"><div class="flex items-center justify-between gap-3"><div><b>{{g.name}}</b><div class="text-xs text-slate-500">{{g.items.length}} recommended products · {{money(g.cost)}}</div></div><button class="primary" @click="createPO(g)">Create Draft PO</button></div><div class="mt-3 max-h-44 overflow-auto text-sm"><div v-for="x in g.items" :key="x.id" class="flex justify-between border-t py-2"><span>{{x.name}}</span><b>{{x.suggested_order}} × {{money(x.buy_price)}}</b></div></div></div></div></section></main></template>
<script setup lang="ts">definePageMeta({layout:'admin',middleware:['admin']});const{adminFetch}=useAdminFetch();const d=ref<any>({summary:{},products:[]}),days=ref(90),target=ref(60),search=ref(''),health=ref(''),err=ref('');const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));const filtered=computed(()=>d.value.products.filter((x:any)=>(!health.value||x.health===health.value)&&(!search.value||`${x.name} ${x.sku||''} ${x.supplier_name||''}`.toLowerCase().includes(search.value.toLowerCase()))));const supplierGroups=computed(()=>{const m=new Map();for(const x of d.value.products.filter((x:any)=>x.suggested_order>0&&x.supplier_id)){if(!m.has(x.supplier_id))m.set(x.supplier_id,{id:x.supplier_id,name:x.supplier_name,items:[],cost:0});const g=m.get(x.supplier_id);g.items.push(x);g.cost+=Number(x.suggested_cost||0)}return [...m.values()].sort((a,b)=>b.cost-a.cost)});function badge(v:string){return 'rounded-full px-2 py-1 text-xs font-black uppercase '+({critical:'bg-red-100 text-red-700',low:'bg-amber-100 text-amber-700',dead:'bg-slate-200 text-slate-700',excess:'bg-purple-100 text-purple-700',slow:'bg-blue-100 text-blue-700',healthy:'bg-emerald-100 text-emerald-700'} as any)[v]}async function load(){err.value='';try{d.value=await adminFetch('/api/admin/accounting/stock-intelligence',{query:{days:days.value,target_days:target.value}})}catch(e:any){err.value=e?.data?.statusMessage||e.message}}async function createPO(g:any){if(!confirm(`Create a draft purchase order for ${g.name} with ${g.items.length} recommended products?`))return;try{const po:any=await adminFetch('/api/admin/accounting/purchase-orders',{method:'POST',body:{supplier_id:g.id,notes:`Created from Stock Intelligence (${days.value}-day sales history, ${target.value}-day target cover)`,lines:g.items.map((x:any)=>({product_id:x.id,description:x.name,sku:x.supplier_sku||x.sku,quantity:x.suggested_order,unit_cost_ex_gst:x.buy_price}))}});alert(`${po.po_number||'Purchase order'} created as draft.`);await load()}catch(e:any){err.value=e?.data?.statusMessage||e.message}}function csv(){const cols=['name','sku','supplier_name','stock','on_order','sold_units','daily_velocity','stock_cover_days','health','suggested_order','buy_price','suggested_cost'];const rows=[cols.join(','),...filtered.value.map((x:any)=>cols.map(k=>`"${String(x[k]??'').replaceAll('"','""')}"`).join(','))];const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([rows.join('\n')],{type:'text/csv'}));a.download=`stock-intelligence-${new Date().toISOString().slice(0,10)}.csv`;a.click();URL.revokeObjectURL(a.href)}onMounted(load)</script>
<style scoped>.panel{@apply rounded-xl border border-slate-200 bg-white shadow-sm}.card{@apply flex min-h-28 flex-col justify-center rounded-xl border border-slate-200 bg-white p-4 shadow-sm}.card small{@apply text-xs font-bold uppercase text-slate-500}.card b{@apply mt-2 text-xl font-black}.input{@apply rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm}.primary{@apply rounded-lg bg-blue-600 px-4 py-2 text-sm font-bold text-white}.secondary{@apply rounded-lg border border-slate-300 bg-white px-4 py-2 text-sm font-bold}</style>
